// ============================================
// VALIDATION INPUT - Image Embedder
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request || '';

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Image parameters (one of them required) ---
const imageUrl = body.image_url || ctx.image_url;
const imageBase64 = body.image_base64 || ctx.image_base64;

if (!imageUrl && !imageBase64) {
  errors.push('image_url ou image_base64 requis');
}

// --- API Keys (passed by the system) ---
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai || '';

if (!openaiApiKey) {
  errors.push('openai_api_key requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// --- Build image URL for API ---
let finalImageUrl = imageUrl;
if (!imageUrl && imageBase64) {
  // Check if it's already a data URL
  if (imageBase64.startsWith('data:')) {
    finalImageUrl = imageBase64;
  } else {
    finalImageUrl = 'data:image/jpeg;base64,' + imageBase64;
  }
}

return {
  valid: true,
  imageUrl: finalImageUrl,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  openaiApiKey: openaiApiKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

