// ============================================
// PARSE RESPONSE - Image Embedder
// ============================================

const items = $input.all();
const prevData = $('Validate Input').first().json;
const visionData = $('OpenAI Vision Embed').first().json;

// --- Build trace helper ---
const buildTrace = (serviceResponse) => ({
  llm_response: visionData,
  service_response: serviceResponse,
  provider: 'openai',
  mode: 'sync',
  latency_ms: Date.now() - (prevData.startTime || Date.now()),
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request
});

const results = items.map(item => {
  if (item.json.error) {
    return {
      json: {
        success: false,
        _trace: buildTrace(item.json),
        error: {
          code: item.json.error.code || 'API_ERROR',
          message: item.json.error.message || 'API error',
          http_status: 500
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini + text-embedding-3-small'
        },
        user_id: prevData.user_id,
        guild_id: prevData.guild_id,
        user_request: prevData.user_request
      }
    };
  }

  try {
    // Parse vision analysis
    let analysis = {};
    try {
      analysis = JSON.parse(visionData.choices?.[0]?.message?.content || '{}');
    } catch (e) {
      analysis = { description: visionData.choices?.[0]?.message?.content || '' };
    }

    // Get embedding
    const embedding = item.json.data?.[0]?.embedding || [];

    return {
      json: {
        success: true,
        _trace: buildTrace(item.json),
        data: {
          embedding: embedding,
          dimensions: embedding.length,
          analysis: {
            description: analysis.description || '',
            objects: analysis.objects || [],
            scene: analysis.scene || '',
            colors: analysis.colors || [],
            mood: analysis.mood || '',
            tags: analysis.tags || [],
            style: analysis.style || ''
          }
        },
        meta: {
          provider: 'openai',
          vision_model: 'gpt-4o-mini',
          embedding_model: 'text-embedding-3-small'
        },
        user_id: prevData.user_id,
        guild_id: prevData.guild_id,
        user_request: prevData.user_request
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        _trace: buildTrace({ error: e.message }),
        error: {
          code: 'PROCESS_ERROR',
          message: 'Failed to process image: ' + e.message,
          http_status: 500
        },
        meta: {
          provider: 'openai'
        },
        user_id: prevData.user_id,
        guild_id: prevData.guild_id,
        user_request: prevData.user_request
      }
    };
  }
});

return results;

